// 화면 리사이징

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
        txb_STD_CD.focus();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS30700.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    $c.cm.PanelToGroupBox(panel_1);

    // 콤보 세팅.
    scwin.setCombo();

    // 기본값 세팅
    scwin.setDefaultVal();
    const array_grid = [grd_List];
    setResizeGrid(array_grid);
    const arrPar = new Array();
    const parentWin = $c.frame.path("../");
    let fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar !== undefined) {
        fn_GetPar(arrPar);
        txb_STD_CD.setValue(((arrPar.length >= 1) && (arrPar[0] !== undefined) ? arrPar[0] : ""));
        txb_ISU_NM.setValue(((arrPar.length >= 1) && (arrPar[1] !== undefined) ? arrPar[1] : ""));
        edt_FROM_TRNSM_DD.setValue(((arrPar.length >= 1) && (arrPar[2] !== undefined) ? arrPar[2] : ""));
        await scwin.ins_search();
    }
};

