/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnDblClick = function(row, colid) {
    try {
        if (row === 0) return;
        if (colid === "STD_CD") {
            const sStdCd = dts_List.getCellData(row, "STD_CD");
            const sContnTpCd = dts_List.getCellData(row, "STD_CD_APPL_CONTN_TP_CD"); // 상품구분
            let sKnd = "";
            if (sContnTpCd === "02") {
                sKnd = "주권";
            } else if (sContnTpCd === "10") {
                sKnd = "주식워런트";
            } else if (sContnTpCd === "11") {
                sKnd = "ELS_DLS";
            } else if (sContnTpCd === "12") {
                sKnd = "전자단기사채";
            }
            if (sContnTpCd === "08") {
                txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
            } else {
                txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
            }
            fn_GetPar = scwin.getParam;
            ins_ViewIsuMaster(sKnd, sStdCd);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS30700.grd_List_OnDblClick" });
    }
};

