};

/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {
    const sToday = $c.ut.cGetToday2();
    edt_FROM_TRNSM_DD.setValue(sToday);
    edt_TO_TRNSM_DD.setValue(sToday);
    panel_5.hide();
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_List.removeAll();
    txb_TotalCnt.setValue("총 0건");
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @param {*} pGubun pGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function(pGubun) {
    if (pGubun === "ins_search") {
        if (edt_FROM_TRNSM_DD.getValue() === "") {
            await $c.win.alert("검색 시작일을 입력하세요.");
            edt_FROM_TRNSM_DD.focus();
            return false;
        }
        if (edt_TO_TRNSM_DD.getValue() === "") {
            await $c.win.alert("검색 종료일을 입력하세요.");
            edt_TO_TRNSM_DD.focus();
            return false;
        }

        // 일자 체크
        if ($c.stf.compareFromToDate2(edt_FROM_TRNSM_DD, edt_TO_TRNSM_DD) === false) {
            return false;
        }

        // 검색기간 일주일 단위 체크.
        if ($c.ut.cGetDifTodayInputday(edt_FROM_TRNSM_DD.getValue(), edt_TO_TRNSM_DD.getValue()) > 6) {
            await $c.win.alert("검색 기간은 일주일 단위로만 가능합니다.");
            return false;
        }
    } else if (pGubun === "ins_Trans") {
        // 조회된 fax가 있는가?
        if (dts_List.getRowCount() === 0) {
            await $c.win.alert("조회된 정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        let nTrueCnt = 0;
        for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
            if (dts_List.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt === 0) {
            await $c.win.alert("선택된 정보가 없습니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name check
 * @description 전송여부가 N인 경우 체크박스 체크
 * @param {*} nRow nRow
 * @param {*} bCheck bCheck
 * @param {*} bMsgShow bMsgShow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.check = async function(nRow, bCheck, bMsgShow) {
    if (dts_List.getCellData(nRow, "TRNSM_YN") === "N") {
        dts_List.setCellData(nRow, "CHK", bCheck ? "T" : "F");
    } else {
        if (bMsgShow) {
            await $c.win.alert("이미 전송된 건입니다.");
        }
        dts_List.setCellData(nRow, "CHK", "F");
    }
};

/**
 * @method
 * @name checkAll
 * @description 전체 체크
 * @param {*} bCheck bCheck
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkAll = async function(bCheck) {
    for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
        await scwin.check(nRow, bCheck, false);
    }
};

